   ```ts
   commitConfirmDiff: async (meetingId) => {
     const state = get();
     const currentSongs = state.songs.filter((s) => s.meetingId === meetingId);
     const snapshot = state.lockSnapshots[meetingId] ?? [];

     // diff 계산
     const snapshotIds = new Set(snapshot.map((s) => s.id));
     const currentIds = new Set(currentSongs.map((s) => s.id));

     const added = currentSongs.filter((s) => !snapshotIds.has(s.id));
     const removed = snapshot.filter((s) => !currentIds.has(s.id));
     const updated = currentSongs.filter((s) => {
       const old = snapshot.find((o) => o.id === s.id);
       return old && (old.title !== s.title || old.artist !== s.artist || ...);
     });

     // Mock BE 호출 시뮬레이션
     const mockResponse = {
       practiceSongs: added.map((s, i) => ({
         meetingSongId: s.id,
         practiceSongId: `ps_${Date.now()}_${i}`,
       })),
     };

     // practiceSongMap 갱신
     set((state) => ({
       meetings: state.meetings.map((m) =>
         m.id === meetingId
           ? {
               ...m,
               practiceSongMap: {
                 ...(m.practiceSongMap ?? {}),
                 ...Object.fromEntries(
                   mockResponse.practiceSongs.map((p) => [p.meetingSongId, p.practiceSongId])
                 ),
               },
             }
           : m
       ),
     }));
   },
   ```

